with with_windows as (select id, store_id, product_id, count(quantity) over (partition by product_id order by quantity, id rows between 6 preceding and current row) last7_count_quantity, avg(quantity) over (partition by product_id order by quantity, id rows between 6 preceding and current row) last7_avg_quantity, min(quantity) over (partition by product_id order by quantity, id rows between 6 preceding and current row) last7_min_quantity, ntile(4) over (partition by product_id order by quantity, id) quantity_bucket from inventory) select s.id, s.store_id, s.last7_count_quantity, s.last7_min_quantity, s.quantity_bucket, (select max(x.quantity) from inventory x where x.store_id = s.store_id) as max_inventory_quantity from with_windows s order by id, store_id;
